const fs = require('fs');
const path = require('path');

// Configuration
const BASE_URL = 'https://personaforge.pehloo.xyz';
const OUTPUT_PATH = path.resolve(__dirname, '../public/sitemap.xml');
const BLOG_DATA_PATH = path.resolve(__dirname, '../.generated/blog-posts.json');

function generateSitemap() {
    console.log('Generating sitemap...');

    let slugs = [];

    // Read slugs from pre-fetched blog data (generated by fetch-blog-data.cjs)
    if (fs.existsSync(BLOG_DATA_PATH)) {
        const posts = JSON.parse(fs.readFileSync(BLOG_DATA_PATH, 'utf8'));
        slugs = posts.map(p => p.slug);
        console.log(`Read ${slugs.length} slugs from .generated/blog-posts.json`);
    } else {
        console.warn('No .generated/blog-posts.json found — sitemap will omit blog post URLs.');
        console.warn('Run `npm run prefetch` first to populate blog data.');
    }

    const date = new Date().toISOString().split('T')[0];

    let sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
    <!-- Static Pages -->
    <url>
        <loc>${BASE_URL}/</loc>
        <lastmod>${date}</lastmod>
        <changefreq>daily</changefreq>
        <priority>1.0</priority>
    </url>
    <url>
        <loc>${BASE_URL}/pricing</loc>
        <lastmod>${date}</lastmod>
        <changefreq>monthly</changefreq>
        <priority>0.8</priority>
    </url>
    <url>
        <loc>${BASE_URL}/blog</loc>
        <lastmod>${date}</lastmod>
        <changefreq>daily</changefreq>
        <priority>0.9</priority>
    </url>
    <url>
        <loc>${BASE_URL}/privacy</loc>
        <lastmod>${date}</lastmod>
        <changefreq>yearly</changefreq>
        <priority>0.3</priority>
    </url>
    <url>
        <loc>${BASE_URL}/terms</loc>
        <lastmod>${date}</lastmod>
        <changefreq>yearly</changefreq>
        <priority>0.3</priority>
    </url>
`;

    // Dynamic Blog Pages — use path-based URLs
    slugs.forEach(slug => {
        sitemap += `    <url>
        <loc>${BASE_URL}/blog/${slug}</loc>
        <lastmod>${date}</lastmod>
        <changefreq>monthly</changefreq>
        <priority>0.7</priority>
    </url>\n`;
    });

    sitemap += '</urlset>';

    fs.writeFileSync(OUTPUT_PATH, sitemap);
    console.log(`Successfully generated sitemap.xml at ${OUTPUT_PATH}`);
    console.log(`Total URLs: ${5 + slugs.length}`);
}

generateSitemap();
